import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';

const ThreadCreate = () => {
    const { id } = useParams();  // Forum ID
    const [title, setTitle] = useState('');
    const [content, setContent] = useState('');
    const [error, setError] = useState(null);
    const [success, setSuccess] = useState(null);
    const navigate = useNavigate();

    const handleSubmit = (e) => {
        e.preventDefault();

        if (!title || !content) {
            setError("All fields are required.");
            return;
        }

        const payload = {
            title,
            content,
            forum_id: id,
        };

        fetch('http://localhost:8741/api/threads', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(payload),
        })
        .then(response => response.json())
        .then(data => {
            setSuccess("Thread created successfully!");
            navigate(`/forum/${id}`);  // Redirect back to the forum after creating the thread
        })
        .catch(error => {
            setError("An error occurred while creating the thread.");
        });
    };

    return (
        <form onSubmit={handleSubmit} className="admin-panel-form">
            <h2>Create a New Thread</h2>

            {error && <div className="error-message">{error}</div>}
            {success && <div className="success-message">{success}</div>}

            <label>
                Title:
                <input 
                    type="text" 
                    value={title} 
                    onChange={(e) => setTitle(e.target.value)} 
                    required 
                />
            </label>

            <label>
                Content:
                <textarea 
                    value={content} 
                    onChange={(e) => setContent(e.target.value)} 
                    required 
                />
            </label>

            <button type="submit">Create Thread</button>
        </form>
    );
};

export default ThreadCreate;
